    /**
     * @param  list<array{question: string, answer: string}>  $faq
     * @param  list<string>  $tags
     * @return array<string, mixed>
     */
    private function guide(
        string $slug,
        string $title,
        string $excerpt,
        string $category,
        array $tags,
        bool $featured,
        bool $trending,
        array $faq,
        int $wordCount,
        string $body,
    ): array {
        return [
            'slug' => $slug,
            'title' => $title,
            'excerpt' => $excerpt,
            'category' => $category,
            'tags' => $tags,
            'is_featured' => $featured,
            'is_trending' => $trending,
            'reading_minutes' => max(5, (int) ceil($wordCount / 180)),
            'faq' => $faq,
            'meta_title' => mb_strlen($title) > 55 ? mb_substr($title, 0, 52).'…' : $title,
            'meta_description' => $excerpt,
            'body' => $body,
        ];
    }
